MOD = 1000000007

def factorization(n):
    arr = []
    temp = n
    for i in range(2, int(-(-n**0.5//1))+1):
        if temp%i==0:
            cnt=0
            while temp%i==0:
                cnt+=1
                temp //= i
            arr.append([i, cnt])

    if temp!=1:
        arr.append([temp, 1])

    if arr==[]:
        arr.append([n, 1])

    return arr


def main():
	n = I()
	divisors_dict = {}
	for i in range(2,n+1):
		tmp_divisors = factorization(i)
		for tmp_divisor, num in tmp_divisors:
			if tmp_divisor in divisors_dict:
				divisors_dict[tmp_divisor] += num
			else:
				divisors_dict[tmp_divisor] = num
	ans = 1
	for divisor_num in divisors_dict.values():
		ans *= (divisor_num + 1)
		ans %= MOD
	print(ans)



