def factorize(N):
  fCount = []
  d = 2
  while d*d <= N:
    if N % d == 0:
      cnt = 0
      while N % d == 0:
        N //= d;
        cnt += 1
      fCount.append(cnt)
    d += 1

  if N > 1: ## N is prime
    fCount.append(1)
    N = 1

  return fCount
