def toHeadTail(n):
    n = str(n)
    head = n[0]
    tail = n[-1]
    return (head, tail)

# 集計処理
def aggregate(N):
    pair_agg = {}
    for i in range(1, N + 1):
        pair = toHeadTail(i)
        if pair in pair_agg.keys():
            pair_agg[pair] += 1
        else:
            pair_agg[pair] = 1
    return pair_agg

