    pdp = [1] * (n)
    for i in range(1 , n):
        pdp[i] = pdp[i - 1] + dp[i]

    for j in range(n):
        for i in range(k):
            if j <= segments[i][1] and j >= segments[i][0]:
                dp[j] += pdp[j - segments[i][0]]
