def bitcount(x):
    x = x - ((x >> 1) & 0x5555555555555555)
    x = (x & 0x3333333333333333) + ((x >> 2) & 0x3333333333333333)
    x = (x + (x >> 4)) & 0x0f0f0f0f0f0f0f0f #8bitごと
    x = x + (x >> 8) #16bitごと
    x = x + (x >> 16) #32bitごと
    x = x + (x >> 32) #64bitごと = 全部の合計
    return x & 0x0000007f

