        if x < W-1:
            if not checked[y][x+1] and grid[y][x+1] == '.':
                next_arr.add((y, x+1))
        if 0 < x:
            if not checked[y][x-1] and grid[y][x-1] == '.':
                next_arr.add((y, x-1))
    if len(next_arr) == 0:
        return -1
    return solve(next_arr, count)


