def rev(val, v1, v2):
    for i in range((v2-v1)//2 +1):
        val[v1+i], val[v2-i] = val[v2-i], val[v1+i]
    return val

def rep(val1, val2, v1, v2):
    for i in range(v2-v1):
        val1[v1+i] = val2[i]
    return val1

