def solve(n, m, grid):
	dp = arr2D(n, m)
	dp[0][0] = 1
	for i in range(n):
		for j in range(m):
			if grid[i][j] == "." and ((i > 0 and grid[i-1][j] == ".") or (j > 0 and grid[i][j-1] == ".")):
				dp[i][j] = (dp[i][j-1] + dp[i-1][j]) % mod
	return dp[n-1][m-1]

