def solve(H: int, W: int, a: "List[List[str]]"):
    dp = [[0] * W for _ in range(H)]
    dp[0][0] = 1
    for h in range(H):
        for w in range(W):
            if h == 0 and w == 0:
                dp[h][w] = 1
            elif h == 0:
                if a[h][0][w-1] == ".":
                    dp[h][w] = dp[h][w-1]
            elif w == 0:
                if a[h-1][0][w] == ".":
                    dp[h][w] = dp[h-1][w]
            else:
                if a[h-1][0][w] == "." and a[h][0][w-1] == ".":
                    dp[h][w] = (dp[h-1][w] + dp[h][w-1]) % MOD
                elif a[h-1][0][w] == ".":
