def connected_components(graph):
    seen = set()
    def component(n):
        nodes = set([n])
        while nodes:
            n = nodes.pop()
            seen.add(n)
            nodes |= set(graph[n]) - seen
            yield n
    for n in graph:
        if n not in seen:
            yield component(n)
print(len([list(x) for x in connected_components(cities)])-1)

import collections
def get_ans(strings, n):
    ans = 0
    for i in range(n):
        counter = collections.defaultdict(int)
        for k in strings:
            counter[k[i]] += 1
        ans += len(strings) - max(counter.values())
    return ans

