class UnionFind:

    def __init__(self,n):
        self.n = n
        self.root=[-1]*(n+1)
        self.rank=[0]*(n+1)

    def findRoot(self,x):
        if(self.root[x] < 0):
            return x
        else:
            self.root[x] = self.findRoot(self.root[x])
            return self.root[x]

    def unite(self,x,y):
        x=self.findRoot(x)
        y=self.findRoot(y)
        if x==y:
            return
        if self.rank[x] > self.rank[y]:
            self.root[x]+=self.root[y]
            self.root[y]=x

        else:
            self.root[y] += self.root[x]
            self.root[x] = y
            if self.rank[x] == self.rank[y]:
                self.rank[y] += 1

    def isSameGroup(self,x,y):
        return self.findRoot(x)==self.findRoot(y)

    def count(self,x):
        return -self.root[self.findRoot(x)]


