ARRY_SIZE = 1000003

def hash1(key):
	return key % (ARRY_SIZE)

def hash2(key):
	return 1 + (key % (ARRY_SIZE - 1))

def hash_combo(key, i):
	return (hash1(key) + i * hash2(key)) % ARRY_SIZE

def insert(arr,key):
	i = 0

	while True:
		j = hash_combo(key, i)
		if arr[j] == "":
			arr[j] = key
			return True
		else:
			i +=  1

def find(arr, key):
	i = 0
	while True:
		j = hash_combo(key,i)
		if arr[j] == key:
			return True
		elif arr[j] == "" or i >= ARRY_SIZE:
			return False
		else:
			i += 1

