class Repeat (object):
	__slots__ = [
		'element',
		'times'
	]

	def __init__(self, element, times : int):
		self.element = element
		self.times = int(times)

	def __len__(self):
		return self.times

	def __iter__(self):
		return iter(self.element for _ in range(self.times))

def repeat(element, times : int):
