class Queue:
    queue_list = []
    start = 0
    def enqueue(self, a):
        self.queue_list.append(a)
    def dequeue(self):
        assert self.start != len(self.queue_list), "オーバーフローが発生しました。"
        self.start += 1
        return self.queue_list[self.start - 1]
    def isEmpty(self):
        return self.start == len(self.queue_list)

