    return answer

def get_same_index(lis):
    if lis[0] == lis[1] == lis[2]:
        return 0, 1, 2
    if lis[0] == lis[1]:
        return 0, 1
    if lis[1] == lis[2]:
        return 1, 2
    if lis[2] == lis[0]:
        return 0, 2
    else:
        return -1


